sql_calls.sql:
SELECT COUNT(*) AS row_count
FROM store.shelf_audits
WHERE audit_ts >= '2026-06-01' AND audit_ts < '2026-07-01';

SELECT sku, name
FROM store.products
WHERE name ILIKE '%curd%';

SELECT DISTINCT tender, till_status
FROM payments.pos_payments
ORDER BY tender, till_status;

SELECT COUNT(*) AS upi_refund_count
FROM payments.upi_refunds
WHERE requested_ts >= '2026-01-01' AND requested_ts < '2027-01-01';

SELECT grn_id, shipment_id, received_ts, receipt_method
FROM store.goods_receipts
WHERE shipment_id IN ('SHP-260611', 'SHP-260615');

SELECT COUNT(*) as products_above_100
FROM store.products
WHERE price_inr > 100;

SELECT table_schema, table_name
FROM information_schema.tables
WHERE table_schema IN ('store', 'warehouse', 'payments');

SELECT sku, name, flow
FROM store.products
WHERE name ILIKE '%milk%';

SELECT DISTINCT note
FROM payments.pos_payments
WHERE note IS NOT NULL;

SELECT SUM(units_sold) as total_units
FROM store.daily_sales
WHERE date >= '2026-06-01' AND date < '2026-07-01';

SELECT sum(units) AS total_units
FROM store.store_orders
WHERE created_ts >= '2026-06-01' AND created_ts < '2026-07-01';

SELECT sku, name, cost_inr
FROM store.products
WHERE name ILIKE '%rice%';
